import {mkdtempSync,rmSync,readFileSync,statSync} from 'node:fs';import {tmpdir} from 'node:os';import {join} from 'node:path';
import {createLoadMetrics} from '../../packages/runtime/load-metrics.mjs';
import {openBindingStore} from '../../packages/runtime/binding-store.mjs';
import {sha256} from '../../packages/runtime/material-import.mjs';import {verifyRoundPetAsset} from '../../packages/runtime/round-pet-material.mjs';
import {NATIVE360} from '../../packages/core/native360-profile.mjs';import {ROOT_CHECKPOINT} from '../../packages/core/round-pet-root-checkpoint.mjs';import {clone,requireThat as need,same} from '../../packages/core/protocol.mjs';
import {rootPersistenceBudget,ROOT_BOUNDS} from '../../packages/simulator/root-persistence-budget.mjs';import {validateRootLoadEvidence} from '../../scripts/lib/root-load-evidence.mjs';
import {createPullLab,pullMedia} from './round-pet-pull-lab.mjs';
const codes={'lease.acquire':1,'lease.renew':2,'playback.set':3,'query.inventory':4,'storage.save':5};
const cp=(binding,media,seq='4',active=[0,4,1,11],gen={0:'1',4:'2',1:'3',11:'4'})=>({schema_version:1,profile:ROOT_CHECKPOINT,binding,namespace:NATIVE360.namespace,floor_seq:seq,floor_commit:null,root:{namespace:NATIVE360.namespace,root_seq:seq,root_state:'OFFLINE_READY',active:active.map(id=>{const a=media.manifest.actions.find(a=>a.id===id);return {action_id:id,asset_sha256:a.sha256,bytes:a.bytes,object_generation:gen[id]};})}});
function register(store,index,media,roots,maximal=false){const key=maximal?String(index).padEnd(80,'D'):`D_${index}`,binding_id=maximal?String(index).padEnd(80,'B'):`B_${index}`;const record={device_id:key,binding_id,binding_epoch:'1',controller_id:maximal?'C'.repeat(80):'C',identity_ref:maximal?'I'.repeat(80):'original_load',credential_epoch:'1',certificate_sha256:sha256(`original-root-load-${index}`),state:'bound',mapping:{},...(roots?{root_checkpoint:null}:{})};let revision=store.read().revision;store.register(revision,record);if(roots){const c=cp({device_id:key,binding_id,binding_epoch:'1'},media);if(maximal){c.floor_seq=c.root.root_seq='18446744073709551615';for(const a of c.root.active){a.bytes=5865472;a.object_generation=c.floor_seq;}c.floor_commit={root_seq:c.floor_seq,...c.root.active[0]};}revision=store.read().revision;store.commitRoot(revision,c);}}
export function measureRootCapacity({rootStrategy='full'}={}){const d=mkdtempSync(join(process.env.HUB_TEST_TMPDIR??tmpdir(),'root-capacity-')),s=openBindingStore({directory:d,create:true,rootState:true,rootStrategy}),media=pullMedia();let failure_operation=0,unchanged_on_failure=true;
 try{for(let i=0;i<64;i++){const before=readFileSync(join(d,'bindings.json'));try{register(s,i,media,true,true);}catch(e){need(e.code==='capacity_exceeded','unexpected_capacity_failure');const now=readFileSync(join(d,'bindings.json'));const data=s.read(),registered=Object.keys(data.bindings).length,rooted=Object.values(data.bindings).filter(r=>r.root_checkpoint!==null).length;failure_operation=registered===rooted?1:2; // register succeeds first, so root failure may leave its explicitly registered null entry.
    if(failure_operation===1)unchanged_on_failure=before.equals(now);else{const r=Object.values(data.bindings).find(r=>r.root_checkpoint===null);need(r,'capacity_root_missing');const expected=s.read().revision;const checkpoint=cp({device_id:r.device_id,binding_id:r.binding_id,binding_epoch:r.binding_epoch},media);checkpoint.floor_seq=checkpoint.root.root_seq='18446744073709551615';for(const a of checkpoint.root.active){a.bytes=5865472;a.object_generation=checkpoint.floor_seq;}checkpoint.floor_commit={root_seq:checkpoint.floor_seq,...checkpoint.root.active[0]};try{s.commitRoot(expected,checkpoint);need(false,'capacity_not_reproduced');}catch(error){need(error.code==='capacity_exceeded');}unchanged_on_failure=now.equals(readFileSync(join(d,'bindings.json')));}break;}}
  if(failure_operation===0){const before=readFileSync(join(d,'bindings.json'));try{register(s,64,media,true,true);need(false,'capacity_not_enforced');}catch(e){need(e.code==='capacity_exceeded');}failure_operation=1;unchanged_on_failure=before.equals(readFileSync(join(d,'bindings.json')));}
  const data=s.read();return {registered:Object.keys(data.bindings).length,rooted:Object.values(data.bindings).filter(r=>r.root_checkpoint!==null).length,file_bytes:statSync(join(d,'bindings.json')).size,failure_operation,unchanged_on_failure};
 }finally{s.close();rmSync(d,{recursive:true,force:true});}}
export async function measureRootPersistenceLoad(pki,{rootStrategy='full'}={}){const profiles=[];
 for(const bindings of [1,64])for(const persistent of [false,true]){const metrics=createLoadMetrics(),lab=await createPullLab(pki,{rootState:persistent,metrics,rootStrategy});try{
  for(let i=1;i<bindings;i++)register(lab.store,i,lab.media,persistent);metrics.reset();const c=lab.client();const t=performance.now();await c.hello();const handshake_ms=performance.now()-t,initial_static_checks=metrics.snapshot().stats.certificate_static?.count??0;metrics.reset();const trace=[],start=performance.now();let asset_bytes=0;
  async function exchange(options){const r=await metrics.measureAsync('control_round_trip',()=>c.exchange(options));if(r.control){need(codes[r.control.kind],'unknown_control');trace.push(codes[r.control.kind]);}return r;}
  async function inventory(seq,ids,gen){lab.pull.query('inventory',lab.deadline());await exchange();const out=clone(c.outgoing);const root=cp({device_id:'D',binding_id:'B',binding_epoch:'1'},lab.media,seq,ids,gen).root;Object.assign(out.record,{known:true,...root});await exchange({observation:out});}
  lab.pull.lease('acquire',lab.deadline());await exchange();await exchange();await inventory('4',[0,4,1,11],{0:'1',4:'2',1:'3',11:'4'});
  const before=metrics.snapshot().counters,revision=JSON.parse(readFileSync(join(lab.directory,'bindings.json'))).content.revision;await inventory('4',[0,4,1,11],{0:'1',4:'2',1:'3',11:'4'});const after=metrics.snapshot().counters,noop={commits:(after.root_commit_calls??0)-(before.root_commit_calls??0),locks:(after.root_lock_acquired??0)-(before.root_lock_acquired??0),file_syncs:(after.root_file_syncs??0)-(before.root_file_syncs??0),directory_syncs:(after.root_directory_syncs??0)-(before.root_directory_syncs??0),write_bytes:(after.root_file_write_bytes??0)-(before.root_file_write_bytes??0),revision_changed:JSON.parse(readFileSync(join(lab.directory,'bindings.json'))).content.revision!==revision};
  let victim=1;for(let round=0;round<3;round++){const id=round%2===0?43:55,m=lab.media.manifest,a=m.actions.find(a=>a.id===id),target={command_id:`load_${round}`,revision:String(round+1),character_id:m.character_id,variant_id:m.variant_id,manifest_sha256:m.sha256,action_id:id,asset_sha256:a.sha256};lab.pull.base(target,lab.deadline());await exchange();await exchange();const parts=[];
   for(let at=0;at<a.bytes;at+=32768){const r=await exchange();need(r.read_permit,'read_permit_missing');parts.push(await metrics.measureAsync('segment_round_trip',()=>c.segment(at,Math.min(at+32767,a.bytes-1),r.read_permit)));}const bytes=Buffer.concat(parts);verifyRoundPetAsset(bytes,a,lab.media.timing);asset_bytes+=bytes.length;
   await exchange({observation:{kind:'record',dispatch_id:null,record:c.record(target,'verified')}});lab.pull.save(lab.deadline(),{victim_action_id:victim});await exchange();const out=clone(c.outgoing),seq=String(5+round);out.record.status='saved';out.record.commit={evidence:'root_commit',root_seq:seq,object_generation:seq};await exchange({observation:out});await inventory(seq,[0,4,11,id],{0:'1',4:'2',11:'4',[id]:seq});victim=id;lab.pull.lease('renew',lab.deadline());await exchange();await exchange();
  }
  metrics.measure('instrumentation_batch',()=>{for(let i=0;i<1000;i++)metrics.measure('instrumentation',()=>{});});profiles.push({bindings,persistent,rounds:3,asset_bytes,file_bytes:statSync(join(lab.directory,'bindings.json')).size,initial_static_checks,handshake_ms,elapsed_ms:performance.now()-start,trace,noop,metrics:metrics.snapshot()});await c.close();
 }finally{await lab.close();const r=lab.resources();need(!r.listening&&r.sockets===0&&r.clients===0&&r.pull.http===0&&r.pull.reads===0,'root_load_cleanup');}}
 for(const p of profiles)need(same(p.trace,profiles[0].trace)&&p.asset_bytes===profiles[0].asset_bytes,'unequal_root_workload');return validateRootLoadEvidence({scope:'host-root-samples-NO_GO_UNTIL_MEASURED',profiles,capacity:measureRootCapacity({rootStrategy}),budget:ROOT_BOUNDS.map(root_service_ms=>rootPersistenceBudget({root_service_ms}))});
}
